indices = gzip.decompress(base64.b64decode(payload_b64))
payload = "".join(alphabet[i] for i in indices)

pattern = re.compile(
    r'(<span\s+class="cell"\s+style="[^"]*">)([^<])(</span>)'
)

text = src.read_text(encoding="utf-8")
matches = list(pattern.finditer(text))

if len(matches) != 15360:
    raise RuntimeError(
        f"Expected 15360 .cell spans, found {len(matches)}"
    )

if len(payload) != 15360:
    raise RuntimeError(
        f"Payload length is {len(payload)}, expected 15360"
    )

it = iter(payload)

def repl(match):
    return match.group(1) + next(it) + match.group(3)

result = pattern.sub(repl, text)
dst.write_text(result, encoding="utf-8", newline="")

sha = hashlib.sha256(dst.read_bytes()).hexdigest()
expected = (
    "d2d98b2f7f45045128294c94a93fcf1"
    "ada0f59a9c43628165f2457764ac74bd2"
)

print(f"Wrote: {dst}")
print(f"Cells replaced: {len(matches)}")
print(f"SHA-256: {sha}")
print(f"Expected: {expected}")
print("MATCH" if sha == expected else "MISMATCH")